using System.Reflection;
using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.Net.Http", "System.Text.Json", "System.IO", "System.Data", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    private static Types TypesOf(string layer) =>
        Types.InAssembly(Assembly.Load(layer)).That().ResideInNamespaceStartingWith(layer);

    private static void AssertNoDependencies(string layer, params string[] forbidden)
    {
        var result = TypesOf(layer).ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        var offenders = string.Join(", ", result.FailingTypeNames ?? []);
        Assert.True(result.IsSuccessful, $"{layer} must not depend on {string.Join(", ", forbidden)}. Offenders: {offenders}");
    }

    [Fact]
    public void Domain_does_not_depend_on_outer_layers() => AssertNoDependencies(Domain, Application, Infrastructure);

    [Fact]
    public void Application_does_not_depend_on_infrastructure() => AssertNoDependencies(Application, Infrastructure);

    [Fact]
    public void Domain_does_not_use_technical_libraries() => AssertNoDependencies(Domain, TechnicalNamespaces);

    [Fact]
    public void Application_does_not_use_technical_libraries() => AssertNoDependencies(Application, TechnicalNamespaces);
}
